package caddyhttp

import (
	"encoding/json"
	"testing"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func repro(t *testing.T, matcher string) {
	input := "not {\n\t" + matcher + " 1.1.1.1\n\t" + matcher + " 2.2.2.2\n\t" + matcher + " 3.3.3.3\n\t}\n"
	d := caddyfile.NewTestDispenser(input)
	var m MatchNot
	if err := m.UnmarshalCaddyfile(d); err != nil {
		t.Fatal(err)
	}
	for _, set := range m.MatcherSetsRaw {
		if raw, ok := set[matcher]; ok {
			var v struct{ Ranges []string }
			if err := json.Unmarshal(raw, &v); err != nil {
				t.Fatal(err)
			}
			t.Logf("%s ranges: %v", matcher, v.Ranges)
		}
	}
}

func TestZZReproClientIP(t *testing.T) { repro(t, "client_ip") }
func TestZZReproRemoteIP(t *testing.T) { repro(t, "remote_ip") }
EOF
